To add a 7-day moving average as a second line on the DAU chart, we need to transform the data by calculating the moving average and then layer the original line chart with a new line chart based on the transformed data.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json",
    "format": {"type": "json"}
  },
  "layer": [
    {
      "mark": "line",
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal",
          "title": "Date"
        },
        "y": {
          "field": "users",
          "type": "quantitative",
          "title": "Daily Active Users"
        }
      }
    },
    {
      "transform": [
        {
          "window": [{"op": "mean", "field": "users", "as": "moving_average"}],
          "frame": [-3, 3]
        }
      ],
      "mark": "line",
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal"
        },
        "y": {
          "field": "moving_average",
          "type": "quantitative"
        },
        "color": {"value": "red"}
      }
    }
  ]
}
```

